    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Graphic feature:
                if (feature != Feature)
                {
                    Feature = feature;
                    ModifiedParameters[nameof(Feature)] = Feature;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case FormTemplate formTemplate:
                if (formTemplate != FormTemplate)
                {
                    FormTemplate = formTemplate;
                    ModifiedParameters[nameof(FormTemplate)] = FormTemplate;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case FeatureFormViewModel viewModel:
                if (viewModel != ViewModel)
                {
                    ViewModel = viewModel;
                    ModifiedParameters[nameof(ViewModel)] = ViewModel;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            case FeatureFormVisibleElements visibleElements:
                if (visibleElements != VisibleElements)
                {
                    VisibleElements = visibleElements;
                    ModifiedParameters[nameof(VisibleElements)] = VisibleElements;
                    if (MapRendered)
                    {
                        await UpdateWidget();
                    }
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Graphic _:
                Feature = null;
                ModifiedParameters[nameof(Feature)] = Feature;
                return true;
            case FormTemplate _:
                FormTemplate = null;
                ModifiedParameters[nameof(FormTemplate)] = FormTemplate;
                return true;
            case FeatureFormViewModel _:
                ViewModel = null;
                ModifiedParameters[nameof(ViewModel)] = ViewModel;
                return true;
            case FeatureFormVisibleElements _:
                VisibleElements = null;
                ModifiedParameters[nameof(VisibleElements)] = VisibleElements;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        Feature?.ValidateRequiredGeneratedChildren();
        FormTemplate?.ValidateRequiredGeneratedChildren();
        ViewModel?.ValidateRequiredGeneratedChildren();
        VisibleElements?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
